import assert from 'node:assert/strict'
import { spawn, execFileSync } from 'node:child_process'
import { existsSync, rmSync, writeFileSync } from 'node:fs'

const BASE='http://127.0.0.1:4173/'
const SOURCE_SHA='88bae394e1de166aceaa2c835a650889b69171f8'
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms))
class Cdp{constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map()}async connect(){this.ws=new WebSocket(this.url);await new Promise((res,rej)=>{const t=setTimeout(()=>rej(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);res()},{once:true});this.ws.addEventListener('error',()=>rej(new Error('ws error')),{once:true})});this.ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)});for(const m of ['Page.enable','Runtime.enable'])await this.send(m)}send(method,params={}){const id=this.id++;return new Promise((res,rej)=>{this.pending.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}))})}async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result?.value}async wait(expression,label,ms=45000){const end=Date.now()+ms;while(Date.now()<end){try{if(await this.eval(`Boolean(${expression})`))return}catch{}await sleep(120)}throw new Error(`timeout ${label}`)}async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length>0`,'root')}async viewport(w,h){await this.send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:w<=390})}async shot(path){const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(path,Buffer.from(r.data,'base64'))}close(){try{this.ws?.close()}catch{}}}
async function launch(){const bin='/usr/bin/google-chrome';assert.ok(existsSync(bin));const version=execFileSync(bin,['--version'],{encoding:'utf8'}).trim();const port=9960+(process.pid%30);const dir=`/tmp/pr19-grid-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(bin,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();const p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(p)return{version,proc,dir,c:new Cdp(p.webSocketDebuggerUrl)}}catch{}await sleep(100)}throw new Error('chrome timeout')}
async function click(c,selector,text){const p=await c.eval(`(()=>{const n=[...document.querySelectorAll(${JSON.stringify(selector)})].find(x=>x.textContent?.trim().includes(${JSON.stringify(text)}));if(!n)return null;n.scrollIntoView({block:'center'});const r=n.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);assert.ok(p,`missing ${text}`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',clickCount:1});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',clickCount:1});await sleep(220)}
async function measure(c){return c.eval(`(()=>{const q=s=>document.querySelector(s);const rect=n=>{if(!n)return null;const r=n.getBoundingClientRect();return{x:+r.x.toFixed(2),y:+r.y.toFixed(2),width:+r.width.toFixed(2),height:+r.height.toFixed(2),bottom:+r.bottom.toFixed(2)}};const css=n=>{if(!n)return null;const s=getComputedStyle(n);return{display:s.display,position:s.position,height:s.height,minHeight:s.minHeight,gridTemplateRows:s.gridTemplateRows,gridAutoRows:s.gridAutoRows,gridRowStart:s.gridRowStart,gridRowEnd:s.gridRowEnd,alignSelf:s.alignSelf}};const shell=q('.research-shell'),kids=shell?[...shell.children].map(n=>({tag:n.tagName,className:n.className,rect:rect(n),css:css(n)})):[];return{innerWidth,innerHeight,scrollY,docHeight:document.documentElement.scrollHeight,shell:{rect:rect(shell),css:css(shell),children:kids},topbar:{rect:rect(q('.research-topbar')),css:css(q('.research-topbar'))},criteria:{rect:rect(q('.criteria-bar')),css:css(q('.criteria-bar'))},entry:{rect:rect(q('.mobile-refine-entry')),css:css(q('.mobile-refine-entry'))},button:{rect:rect(q('.mobile-refine-entry button')),css:css(q('.mobile-refine-entry button'))},workspace:{rect:rect(q('.research-workspace')),css:css(q('.research-workspace'))},panel:{rect:rect(q('#mobile-recipe-refine-panel')),css:css(q('#mobile-recipe-refine-panel'))},filterScroll:{rect:rect(q('.research-filter-scroll')),css:css(q('.research-filter-scroll'))},refineTitle:{rect:rect(q('.refine-title')),css:css(q('.refine-title'))},search:{rect:rect(q('.recipe-search')),css:css(q('.recipe-search'))}}})()`)}
const {version,proc,dir,c}=await launch();const report={browserVersion:version,sourceSha:SOURCE_SHA,cases:{}};try{await c.connect();for(const [w,h] of [[360,844],[390,900]]){await c.viewport(w,h);await c.nav(BASE+'?view=workspace&applied=1');await c.wait(`document.querySelectorAll('.research-result-card').length>0`,'results');await click(c,'.mobile-refine-entry button','더 좁혀보기');await c.wait(`document.querySelector('.mobile-refine-entry button')?.getAttribute('aria-expanded')==='true'&&document.querySelector('.recipe-search')`,'open');await c.eval('window.scrollTo(0,0)');await sleep(250);const m=await measure(c);report.cases[`${w}x${h}`]=m;await c.shot(`qa-artifacts/old-${w}x${h}-open.png`)}writeFileSync('qa-artifacts/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2))}finally{c.close();proc.kill('SIGTERM');await sleep(200);if(proc.exitCode==null)proc.kill('SIGKILL');rmSync(dir,{recursive:true,force:true})}
